tasks.powerShellScript:
# Activation des touches rémanentes (StickyKeys) dans le registre utilisateur
Set-ItemProperty -Path 'HKCU:\Control Panel\Accessibility\StickyKeys' -Name 'Flags' -Value '511'
# Permutation bouton principal souris (1 = Gaucher / bouton droit principal)
[System.Runtime.InteropServices.Marshal]::GetLastWin32Error() | Out-Null
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class MouseSwap {
    [DllImport("user32.dll")]
    public static extern Int32 SwapMouseButton(Int32 bSwap);
}
"@
[MouseSwap]::SwapMouseButton(1)
